window.OAT_CONTENT = window.OAT_CONTENT || {};
window.OAT_CONTENT.reading = {
  id: 'reading',
  name: 'Reading Comprehension',
  short: 'Reading',
  icon: '📖',
  blurb: '50 questions across 3 science passages in 60 minutes. No outside knowledge is required — every answer is supported by the text. The skill is locating and reasoning, not recall.',
  review: [
    {
      id: 'strategy',
      title: 'Passage Strategy',
      html: `
        <p>The OAT reading section uses dense, science-style passages, but you are <strong>never</strong> expected to know the topic beforehand. Every correct answer is defensible from the text alone. Bring evidence, not opinion.</p>
        <h3>How to read</h3>
        <ul>
          <li>Don't memorize details on the first pass. Read for <strong>structure</strong>: what is each paragraph doing, and where is each kind of information located?</li>
          <li>Note the main idea (usually early), the author's purpose, and any shift words ("however," "in contrast," "therefore").</li>
          <li>When a question asks about a detail, <strong>go back and find it</strong>. Do not answer from memory — the wrong answers are built to sound plausible.</li>
        </ul>
        <div class="callout"><strong>Search-and-destroy vs. read-first:</strong> Many high scorers skim the passage for structure (1–2 min), then attack questions, returning to the text for each detail. Try both approaches on practice passages and keep whichever gives you better accuracy within the time limit.</div>
      `
    },
    {
      id: 'qtypes',
      title: 'Question Types & Traps',
      html: `
        <h3>Common question types</h3>
        <ul>
          <li><strong>Main idea / purpose</strong> — the answer covers the whole passage, not one paragraph. Eliminate choices that are too narrow or too broad.</li>
          <li><strong>Detail / fact</strong> — directly stated; scan for keywords from the question.</li>
          <li><strong>Inference</strong> — not stated outright but strongly supported. If you must assume information not in the passage, it's wrong.</li>
          <li><strong>Tone / attitude</strong> — driven by the author's word choices. Look for evaluative language.</li>
          <li><strong>Function</strong> — why did the author include this sentence or example?</li>
        </ul>
        <h3>Wrong-answer patterns to recognize</h3>
        <ul>
          <li><strong>Too extreme</strong> — absolute words like "always," "never," "proves" often signal a trap.</li>
          <li><strong>Half-right</strong> — one clause matches the passage, the other contradicts it. Read the whole choice.</li>
          <li><strong>Out of scope</strong> — true in the real world but never mentioned in the passage.</li>
          <li><strong>Reversed</strong> — states the opposite of what the passage says.</li>
        </ul>
      `
    },
    {
      id: 'timing',
      title: 'Timing',
      html: `
        <ul>
          <li>Three passages in 60 minutes → about <strong>20 minutes per passage</strong>, including its questions.</li>
          <li>Answer the questions you're confident about first; flag and return to the hard ones.</li>
          <li>There is no penalty for guessing — never leave a question blank, even if you have to guess in the final seconds.</li>
          <li>Don't over-invest in a single stubborn question; the 12th question is worth as much as the 1st.</li>
        </ul>
      `
    }
  ],
  passages: [
    {
      id: 'p1',
      title: 'Passage I — The Aging Lens',
      html: `
        <p><span class="pnum">[1]</span> The human eye focuses light through a transparent, flexible structure called the crystalline lens. In a young eye, the lens is pliable, and tiny muscles surrounding it can change its shape to bring objects at different distances into sharp focus, a process known as accommodation. When the eye views a nearby object, the ciliary muscle contracts, the lens thickens, and its focusing power increases. For distant objects, the muscle relaxes and the lens flattens.</p>
        <p><span class="pnum">[2]</span> With age, the lens gradually loses its flexibility. Proteins within the lens, called crystallins, become progressively cross-linked and less soluble over the decades. The consequence is a steady decline in the lens's ability to change shape. This condition, presbyopia, typically becomes noticeable in the mid-forties, when many people find they must hold reading material at arm's length. Presbyopia is not a disease but an essentially universal feature of aging; corrective reading lenses compensate for the lost focusing range rather than reversing the underlying change.</p>
        <p><span class="pnum">[3]</span> The same crystallin proteins are implicated in a distinct age-related problem: cataract. Whereas presbyopia reflects a loss of flexibility, a cataract is a loss of transparency. As damaged crystallins clump together, they scatter incoming light, and vision becomes cloudy or hazy. Unlike presbyopia, cataracts can be treated surgically by replacing the clouded natural lens with a clear artificial one. Notably, an artificial lens implant is rigid; it restores clarity but not the eye's youthful ability to accommodate, so many patients still require reading glasses afterward.</p>
        <p><span class="pnum">[4]</span> Researchers continue to investigate why crystallins deteriorate. Ultraviolet exposure, oxidative stress, and simple accumulated time all appear to contribute. Because the lens produces very few new proteins across a lifetime, the crystallins present in old age are, remarkably, largely the same molecules formed before birth. This longevity leaves them uniquely vulnerable to a lifetime of gradual chemical damage that other, more frequently replaced proteins in the body escape.</p>
      `,
      questions: [
        { id:'rd1', topic:'Detail', stem:'According to the passage, what happens in the eye when it shifts from viewing a distant object to viewing a nearby one?', options:['The ciliary muscle relaxes and the lens flattens, reducing its focusing power','The ciliary muscle contracts and the lens thickens, increasing its focusing power','The crystallins within the lens become cross-linked and less soluble','Damaged proteins clump together and scatter the incoming light'], answer:1, explanation:'Paragraph 1 spells out both halves of accommodation: "When the eye views a nearby object, the ciliary muscle contracts, the lens thickens, and its focusing power increases," while "for distant objects, the muscle relaxes and the lens flattens." The question asks about the shift toward a near object, so the contraction/thickening description is correct. The relax-and-flatten choice is the classic reversal trap — it is a true statement about distance viewing, but it describes the opposite direction of the shift the stem asks about. The cross-linking choice comes from paragraph 2 and describes a decades-long aging change in the crystallins, not a moment-to-moment focusing adjustment, and the light-scattering choice describes cataract formation in paragraph 3.' },
        { id:'rd2', topic:'Main Idea', stem:'Which statement best captures the central distinction the passage develops between presbyopia and cataract?', options:['They are early and late stages of one continuous degenerative process','Both are corrected by replacing the natural lens with an artificial one','Cataract develops only in eyes that have already become presbyopic','Presbyopia is a loss of lens flexibility, whereas cataract is a loss of lens transparency'], answer:3, explanation:'Paragraph 3 states the contrast in almost exactly these words: "Whereas presbyopia reflects a loss of flexibility, a cataract is a loss of transparency." Paragraph 2 supports the first half by tracing presbyopia to a lens that can no longer change shape, and paragraph 3 supports the second by describing clumped crystallins that scatter light. The most tempting wrong answer is the one about surgical replacement: paragraph 3 does say a cataract can be treated by implanting a clear artificial lens, but the passage never offers surgery as a correction for presbyopia — it says reading lenses merely compensate for presbyopia rather than reversing it, so that choice is half-right at best. The choices calling the two conditions stages of one process, or making presbyopia a prerequisite for cataract, assert a sequential link the passage never makes; both conditions involve crystallins, but a shared protein is not a shared progression.' },
        { id:'rd3', topic:'Inference', stem:'The passage most strongly supports which prediction about a patient whose clouded natural lens has been replaced with an artificial one?', options:['The patient will recover the full accommodative range of a young eye','The patient will see clearly at distance but is likely to need reading glasses for near work','The patient will no longer require corrective lenses of any kind','The patient\'s lens will gradually lose transparency again as new crystallins accumulate'], answer:1, explanation:'Paragraph 3 supplies every piece of this inference: the implant "is rigid; it restores clarity but not the eye\'s youthful ability to accommodate, so many patients still require reading glasses afterward." Clarity restored plus accommodation not restored yields exactly the predicted outcome. The choices promising full youthful accommodation or freedom from all corrective lenses are the extreme versions of that same sentence — they take the "restores clarity" half and ignore the explicit "but not... accommodate" qualification. The choice predicting renewed clouding contradicts paragraph 4, which notes that the lens produces very few new proteins across a lifetime; nothing in the passage suggests an artificial implant re-clouds.' },
        { id:'rd4', topic:'Detail', stem:'The passage attributes the unusual vulnerability of crystallins to chemical damage primarily to the fact that:', options:['The lens makes very few new proteins, so its crystallins persist from before birth','The lens replaces its proteins more frequently than other tissues in the body do','Crystallins are the only proteins in the body affected by ultraviolet light','Crystallins remain more soluble than other proteins throughout life'], answer:0, explanation:'Paragraph 4 explains that "because the lens produces very few new proteins across a lifetime, the crystallins present in old age are, remarkably, largely the same molecules formed before birth," and that "this longevity leaves them uniquely vulnerable to a lifetime of gradual chemical damage." The vulnerability comes from persistence, not from any special chemical fragility. The choice about frequent replacement reverses the passage: it is the more frequently replaced proteins elsewhere in the body that escape the damage. The ultraviolet choice is too extreme — paragraph 4 lists UV exposure as one contributor among several (along with oxidative stress and accumulated time) but never claims crystallins are the only proteins it affects. The solubility choice reverses paragraph 2, which says crystallins become progressively less soluble with age.' },
        { id:'rd5', topic:'Function', stem:'The author\'s remark that presbyopia "is not a disease but an essentially universal feature of aging" functions mainly to:', options:['Discourage the use of corrective reading lenses for an unavoidable change','Establish that presbyopia is a more serious problem than cataract','Frame presbyopia as a normal aging process rather than a pathological condition','Suggest that presbyopia can be delayed by limiting ultraviolet exposure'], answer:2, explanation:'The clause sits at the end of paragraph 2 and does classification work: it labels presbyopia as ordinary and universal, which sets up the contrast in paragraph 3 with cataract, a distinct problem the passage treats as a treatable disorder requiring surgery. The most tempting wrong answer is the one about discouraging correction, because the same sentence goes on to say reading lenses "compensate for the lost focusing range rather than reversing the underlying change" — but noting that a correction is compensatory rather than curative is not the same as advising against it, and the author never discourages correction. The severity comparison is a judgment the passage never makes, and the ultraviolet choice borrows from paragraph 4, where UV is offered as a contributor to crystallin deterioration generally, with no claim that avoiding it delays presbyopia.' }
      ]
    },
    {
      id: 'p2',
      title: 'Passage II — Antibiotic Resistance',
      html: `
        <p><span class="pnum">[1]</span> When antibiotics were introduced in the mid-twentieth century, they transformed medicine, turning once-lethal infections into routine, treatable conditions. Yet within years of each new drug's release, bacteria capable of surviving it began to appear. This pattern is not a coincidence but a direct consequence of natural selection operating on enormous bacterial populations.</p>
        <p><span class="pnum">[2]</span> A single bacterial colony may contain billions of cells, and random mutations arise constantly during replication. Most mutations are harmful or neutral, but occasionally one confers the ability to survive a particular antibiotic. When the drug is applied, susceptible cells die while the rare resistant cell survives and multiplies. In a short time, the descendants of that single survivor can dominate the population. The antibiotic does not create resistance; it merely selects for resistance that variation had already produced.</p>
        <p><span class="pnum">[3]</span> Bacteria have an additional advantage that most organisms lack. Through a process called horizontal gene transfer, they can share genetic material directly with unrelated cells, sometimes even across species. A gene for resistance that arises in one type of bacterium can therefore spread to others without inheritance through reproduction. This capacity accelerates the diffusion of resistance far beyond what ordinary descent would allow.</p>
        <p><span class="pnum">[4]</span> Human practices have intensified the problem. The incomplete use of prescribed courses, the use of antibiotics to treat viral illnesses they cannot affect, and their routine addition to livestock feed all expose bacteria to drugs under conditions that favor resistant strains. Some researchers warn of a future in which common infections again become difficult to treat. Others counter that new strategies, from narrowly targeted drugs to therapies using viruses that infect bacteria, may yet shift the balance. What both sides accept is that resistance cannot be eliminated, only managed, because the evolutionary pressure that produces it is inseparable from the use of the drugs themselves.</p>
      `,
      questions: [
        { id:'rd6', topic:'Main Idea', stem:'The primary purpose of the passage is to:', options:['Explain how antibiotic resistance emerges, spreads among bacteria, and is intensified by human practices','Argue that antibiotics should be withdrawn from use before resistance becomes universal','Demonstrate that horizontal gene transfer is the single cause of antibiotic resistance','Trace the history of antibiotics from their mid-century introduction to the present day'], answer:0, explanation:'Each paragraph contributes one piece of a single explanatory arc: paragraph 1 establishes that resistance follows every new drug because of natural selection, paragraph 2 details the selection mechanism within a population, paragraph 3 adds horizontal gene transfer as an accelerant, and paragraph 4 describes the human practices that intensify the pressure. Only the explanatory choice covers that whole span. The horizontal-gene-transfer choice is too narrow and too absolute — paragraph 3 presents horizontal gene transfer as an "additional advantage" layered on top of mutation and selection, not the sole cause. The call to withdraw antibiotics is the reverse of the author\'s position: paragraph 4 closes by saying resistance "cannot be eliminated, only managed," which presumes continued use of the drugs. The historical choice mistakes the passage\'s opening detail about the mid-twentieth century for its overall project.' },
        { id:'rd7', topic:'Detail', stem:'According to the passage, what does an antibiotic actually do to a bacterial population?', options:['It induces the mutations that make surviving cells resistant','It halts replication so thoroughly that new mutations can no longer arise','It kills susceptible cells, allowing rare cells that were already resistant to multiply','It blocks the sharing of resistance genes between unrelated cells'], answer:2, explanation:'Paragraph 2 describes the sequence directly: random mutations arise constantly during replication, and "when the drug is applied, susceptible cells die while the rare resistant cell survives and multiplies." The paragraph then states the point outright — the antibiotic "does not create resistance; it merely selects for resistance that variation had already produced." The choice that has the drug inducing mutations is the trap the passage was written to correct: it reverses cause and effect by making the antibiotic the source of the mutation rather than the filter acting on variation that preexisted it. The choice about halted replication contradicts the same paragraph, which says mutations arise constantly during replication, and the gene-sharing choice reverses paragraph 3, where horizontal gene transfer spreads resistance rather than being blocked by the drug.' },
        { id:'rd8', topic:'Detail', stem:'According to paragraph 3, horizontal gene transfer matters chiefly because it allows bacteria to:', options:['Replicate faster than the antibiotic can kill them','Acquire resistance genes from unrelated cells without inheriting them through reproduction','Become permanently immune to every antibiotic they encounter','Survive antibiotic exposure without any mutation ever having occurred'], answer:1, explanation:'Paragraph 3 defines the process as sharing genetic material "directly with unrelated cells, sometimes even across species," so that a resistance gene arising in one type of bacterium "can spread to others without inheritance through reproduction," which "accelerates the diffusion of resistance far beyond what ordinary descent would allow." The significance is the route of transmission, not the speed of reproduction, which rules out the replication-rate choice. The permanent-immunity choice is the too-extreme version: sharing one resistance gene is a long way from immunity to every drug, and the passage never claims that. The choice denying any role for mutation is half-right in a misleading way — transfer does bypass inheritance for the recipient cell, but paragraph 2 makes clear the gene still originates in mutation somewhere in the population.' },
        { id:'rd9', topic:'Inference', stem:'The passage implies that prescribing an antibiotic for a viral illness worsens resistance because:', options:['The antibiotic molecule loses potency each time it is administered','Antibiotics clear viral infections too slowly to be useful','Viruses can pick up resistance genes from bacteria through horizontal gene transfer','The drug cannot act on the virus, yet it still exposes the patient\'s bacteria to selective pressure'], answer:3, explanation:'Paragraph 4 groups this practice with incomplete courses and livestock feed as practices that "expose bacteria to drugs under conditions that favor resistant strains," and it specifies that the antibiotics are being used against "viral illnesses they cannot affect." Combine that with the selection mechanism in paragraph 2 and the inference follows: the dose does nothing to the virus but still kills susceptible bacteria and clears the field for resistant ones. The "too slowly" choice is the half-right trap — it concedes some effect on the virus, whereas the passage says antibiotics cannot affect viruses at all. The choice about viruses acquiring resistance genes misapplies paragraph 3, which describes transfer between bacterial cells; the only viruses the passage mentions are the ones proposed as a therapy that infects bacteria. The claim about the molecule losing potency is out of scope, since the passage locates the change in bacterial populations, never in the drug itself.' },
        { id:'rd10', topic:'Tone', stem:'How would you best describe the author\'s treatment of the future of antibiotic resistance in the final paragraph?', options:['Convinced that common infections will inevitably become untreatable','Dismissive of researchers who raise alarms about resistance','Measured, giving weight both to the warnings and to possible countermeasures','Detached, reporting the debate without identifying any point of agreement'], answer:2, explanation:'Paragraph 4 sets the two camps side by side without endorsing either: "some researchers warn of a future in which common infections again become difficult to treat," while "others counter that new strategies, from narrowly targeted drugs to therapies using viruses that infect bacteria, may yet shift the balance." The author then names what both sides accept — that resistance can only be managed, not eliminated. That even-handed framing plus a stated common ground is exactly a measured tone. The "inevitably untreatable" choice adopts only the pessimistic camp and hardens "difficult to treat" into a certainty the author never asserts. The dismissive choice reverses the passage, which reports the warnings neutrally rather than deriding them. The detached choice is the closest miss: the author does stay neutral between camps, but "detached" fails on the second half, since the paragraph ends by identifying precisely the point both sides accept.' }
      ]
    },
    {
      id: 'p3',
      title: 'Passage III — Coral Bleaching',
      html: `
        <p><span class="pnum">[1]</span> Coral reefs, often called the rainforests of the sea, owe their vivid colors and biological productivity to a partnership between coral animals and microscopic algae called zooxanthellae. These algae live within the coral's tissue, and through photosynthesis they supply the coral host with most of its energy, while the coral in turn provides the algae a protected, sunlit habitat and a steady supply of carbon dioxide and nutrients. This mutualism is so central to reef ecology that most reef-building corals cannot survive for long without it.</p>
        <p><span class="pnum">[2]</span> When corals are subjected to prolonged stress, most commonly a sustained rise in water temperature of even one or two degrees Celsius above the seasonal maximum, this partnership breaks down. The coral expels its zooxanthellae, and because the algae's pigments are responsible for most of the coral's color, the exposed white calcium carbonate skeleton becomes visible through the coral's now nearly transparent tissue. This is the event referred to as coral bleaching. Critically, a bleached coral is not dead; it is a coral that has lost its primary energy source and is now surviving on reserves and on whatever it can capture directly from the water with its tentacles.</p>
        <p><span class="pnum">[3]</span> Whether a bleached coral recovers depends largely on how long the stressful conditions persist. If water temperatures return to normal within a matter of weeks, many corals can reacquire zooxanthellae, either from algae remaining in nearby tissue or from the surrounding water, and gradually regain their color and function. If elevated temperatures persist longer, the coral's energy reserves are exhausted before the partnership can be reestablished, and the coral starves and dies, leaving behind a bare skeleton that is quickly colonized by turf algae rather than by reef-building organisms.</p>
        <p><span class="pnum">[4]</span> Because bleaching events are triggered by temperature rather than by a single pathogen or pollutant, they can strike reefs across enormous geographic areas simultaneously whenever ocean temperatures spike, as during a strong El Niño event. Some coral species and some individual coral colonies, however, tolerate thermal stress far better than others, an observation that has led researchers to investigate whether corals from unusually warm environments might be selectively propagated or interbred with more vulnerable populations to produce reefs with greater resilience to a warming ocean.</p>
      `,
      questions: [
        { id:'rd11', topic:'Detail', stem:'According to the passage, what is the direct cause of a bleached coral\'s white or pale appearance?', options:['The coral\'s calcium carbonate skeleton becoming visible once the coral expels its pigmented algae','The coral secreting a white protective mucus layer in response to thermal stress','The zooxanthellae themselves turning white as they die inside the coral\'s tissue','Turf algae colonizing the coral\'s surface and bleaching its natural pigment'], answer:0, explanation:'Paragraph 2 states the mechanism directly: once the coral expels its zooxanthellae, "the exposed white calcium carbonate skeleton becomes visible through the coral\'s now nearly transparent tissue." The mucus-layer choice invents a mechanism the passage never mentions. The choice about algae turning white reverses the actual event — the algae are expelled by the coral, not killed and discolored in place. And turf algae colonizing the coral appears only in paragraph 3, describing what happens to an already-dead skeleton after the coral has died — a later, separate event, not the cause of the color change itself.' },
        { id:'rd12', topic:'Main Idea', stem:'The primary purpose of the passage is to:', options:['Explain the coral-algae partnership, describe how and why it breaks down under heat stress, and outline the range of possible outcomes','Argue that coral bleaching is caused exclusively by pollution rather than by rising ocean temperatures','Prove that all bleached coral colonies inevitably die within a period of several weeks','Compare the recovery rates of specific named coral species in quantitative detail'], answer:0, explanation:'Each paragraph builds the same account: paragraph 1 establishes the mutualism, paragraph 2 explains the bleaching mechanism, paragraph 3 lays out the two possible outcomes depending on how long stress persists, and paragraph 4 broadens to geographic scale and resilience research. The pollution choice contradicts the passage, which attributes bleaching to temperature stress, never mentioning pollution at all. The choice about inevitable death overstates paragraph 3, which explicitly says the outcome "depends" on conditions and describes both recovery and death as possible. And the passage never compares specific named species in quantitative detail — it discusses general patterns and open research questions instead.' },
        { id:'rd13', topic:'Inference', stem:'Based on paragraph 4, what would the passage most likely predict about two coral colonies of the same species living in reefs with different typical water temperatures, if both experience an identical spike in temperature?', options:['The colony from the warmer typical environment might tolerate the spike better, based on the passage\'s observation that thermal tolerance varies among colonies','They would respond identically, since bleaching depends only on the spike\'s absolute magnitude, not on the reef\'s baseline conditions','The colony from the cooler typical environment would necessarily bleach less, having experienced less cumulative thermal stress over its lifetime','Neither colony would bleach at all, since bleaching only occurs during a confirmed El Niño event'], answer:0, explanation:'Paragraph 4 states that "some individual coral colonies... tolerate thermal stress far better than others" and specifically flags "corals from unusually warm environments" as candidates for greater resilience — implying colonies already adapted to warmer baseline conditions may better withstand an additional spike. The "identical response" choice directly contradicts the variability the passage describes. The "necessarily" choice makes an overly definite claim the passage never asserts, and paragraph 4\'s framing actually points the opposite direction, toward warmer-adapted colonies faring better. And El Niño is offered only as one example ("as during") of a temperature-spike-triggering event, not as bleaching\'s sole possible cause.' },
        { id:'rd14', topic:'Function', stem:'The author\'s mention of an El Niño event in paragraph 4 functions primarily to:', options:['Illustrate a real-world scenario capable of producing simultaneous, widespread ocean temperature spikes across large geographic areas','Introduce a second, entirely separate cause of coral bleaching distinct from temperature','Argue that bleaching events are becoming less frequent than they were in the past','Explain why bleached corals eventually recover their zooxanthellae populations'], answer:0, explanation:'The sentence reads "...they can strike reefs across enormous geographic areas simultaneously whenever ocean temperatures spike, as during a strong El Niño event" — El Niño is offered as an example of the temperature-spike mechanism already established, not a new cause layered on top of it. The "second cause" choice misreads that example as an independent trigger. The frequency-trend choice is unsupported; the passage never discusses how bleaching frequency has changed over time. And El Niño\'s mention has nothing to do with paragraph 3\'s separate discussion of recovery conditions.' },
        { id:'rd15', topic:'Tone', stem:'How would you best characterize the author\'s tone when discussing the possibility of breeding more resilient coral populations in paragraph 4?', options:['Cautiously informative, presenting it as an active area of investigation rather than a settled solution','Dismissive, suggesting the approach is unlikely to ever succeed','Alarmed, warning that such interventions could cause unintended ecological harm','Fully confident, asserting that this strategy will resolve the coral bleaching crisis'], answer:0, explanation:'The passage\'s hedged phrasing — researchers "investigate whether" corals "might be" propagated or interbred — signals an open research question rather than a settled conclusion, matching a cautiously informative tone. Nothing in the text expresses doubt or mockery about the approach\'s viability, ruling out the dismissive choice. No unintended-harm concern is ever raised, ruling out the alarmed choice. And "fully confident" overstates the certainty far past what tentative language like "might" and "investigate whether" actually supports.' }
      ]
    },
    {
      id: 'p4',
      title: 'Passage IV — The Discovery of Penicillin',
      html: `
        <p><span class="pnum">[1]</span> In September 1928, the bacteriologist Alexander Fleming returned to his London laboratory after a summer holiday to find that one of the culture dishes he had left out was contaminated with a stray mold. Rather than discarding the dish, as most researchers might have, Fleming examined it closely and noticed something unusual: in a clear ring surrounding the mold colony, the bacteria he had been growing, a strain of Staphylococcus, had failed to grow at all. Something produced by the mold was killing the bacteria nearby.</p>
        <p><span class="pnum">[2]</span> Fleming identified the mold as a species of Penicillium and named the bacteria-killing substance it secreted penicillin. He published his observation in 1929, noting its potential to inhibit bacterial growth, but he lacked the chemical training to isolate and purify the compound in any quantity, and his early attempts to interest chemists in the project largely failed. For roughly a decade, penicillin remained a laboratory curiosity, mentioned occasionally in the scientific literature but never developed into a usable treatment.</p>
        <p><span class="pnum">[3]</span> The compound's fortunes changed only when a team at Oxford University, led by Howard Florey and Ernst Chain, took up the problem in the late 1930s. Where Fleming had been a bacteriologist observing an effect, Florey and Chain were, respectively, a pathologist and a biochemist equipped to solve the practical problem Fleming could not: extracting a stable, concentrated form of penicillin from the mold culture. After extensive difficulty producing enough of the compound, their team successfully purified it and, in 1940, demonstrated that it could cure infected mice that would otherwise have died. Human trials followed within two years, with dramatic results in patients suffering from infections that had previously been untreatable.</p>
        <p><span class="pnum">[4]</span> The outbreak of the Second World War transformed penicillin from a promising laboratory finding into an urgent industrial priority. Wound infection was a major cause of death among soldiers, and British and American manufacturers raced to scale up production methods that had, until then, yielded only tiny quantities of the drug from laboratory cultures. By the time of the Allied invasion of Normandy in 1944, penicillin was being produced in large enough quantities to treat wounded soldiers on a wide scale, a transformation from laboratory curiosity to mass-produced medicine that took less than five years once the Oxford team's work began in earnest. Fleming, Florey, and Chain shared the 1945 Nobel Prize in Physiology or Medicine for the discovery.</p>
      `,
      questions: [
        { id:'rd16', topic:'Detail', stem:'According to the passage, what specifically did Fleming observe on the contaminated culture dish that led him to investigate further?', options:['A clear zone around the mold colony in which the bacteria he had been culturing failed to grow','The mold colony itself had failed to grow anywhere near the edges of the dish','The bacteria had changed color after coming into contact with the mold','The mold had completely displaced and physically overgrown the bacterial colony'], answer:0, explanation:'Paragraph 1 states it directly: "in a clear ring surrounding the mold colony, the bacteria he had been growing... had failed to grow at all." The second choice reverses which organism failed to grow — it was the bacteria near the mold, not the mold itself anywhere on the dish. The color-change choice invents a detail never mentioned. And the "physically overgrown" choice mischaracterizes the mechanism as displacement rather than the described chemical inhibition creating a clear, bacteria-free zone.' },
        { id:'rd17', topic:'Main Idea', stem:'The primary purpose of the passage is to:', options:['Trace penicillin\'s path from an accidental laboratory observation to a mass-produced wartime medicine, and credit the distinct contributions that made each step possible','Argue that Alexander Fleming deserves sole credit for the discovery and development of penicillin','Explain the biochemical mechanism by which penicillin kills bacterial cells','Compare the relative merits of British versus American pharmaceutical manufacturing during World War II'], answer:0, explanation:'Paragraphs 1–2 cover Fleming\'s accidental discovery and its stalled early fate; paragraph 3 covers Florey and Chain\'s purification breakthrough; paragraph 4 covers wartime industrial scale-up — together tracing the full arc and explicitly crediting each distinct contribution, as when the passage notes Florey and Chain were "equipped to solve the practical problem Fleming could not." The "sole credit" choice contradicts the passage directly: the Nobel Prize was shared among all three, and paragraph 3 emphasizes what Florey and Chain contributed that Fleming could not. The biochemical-mechanism choice is out of scope — no such mechanism is ever described. And the passage mentions British and American manufacturers racing to scale up production but never compares or ranks them.' },
        { id:'rd18', topic:'Inference', stem:'The passage most strongly supports which conclusion about the decade following Fleming\'s original 1929 publication?', options:['Penicillin\'s therapeutic potential remained largely unrealized primarily due to a lack of the chemical expertise needed to isolate and purify it in usable form','Fleming spent the decade attempting unsuccessfully to enlist Florey and Chain specifically to purify the compound','Penicillin was already in limited clinical use during this period, though not yet mass-produced','Other researchers had disproven Fleming\'s original observation about penicillin\'s bacteria-killing effect'], answer:0, explanation:'Paragraph 2 states that Fleming "lacked the chemical training to isolate and purify the compound in any quantity" and that his attempts to interest chemists largely failed, so penicillin "remained a laboratory curiosity" — the gap was expertise and purification, not doubt about the effect itself. The choice naming Florey and Chain specifically is unsupported: they are introduced only in paragraph 3 as taking up the problem in the late 1930s, with no indication Fleming had been pursuing them by name throughout the prior decade. The "already in limited clinical use" choice directly contradicts the passage, which says penicillin was "never developed into a usable treatment" during this period. And nothing suggests the original observation was ever disputed — the obstacle was always purification and production, not the finding\'s validity.' },
        { id:'rd19', topic:'Function', stem:'The author\'s statement that Fleming, Florey, and Chain "shared the 1945 Nobel Prize" functions primarily to:', options:['Reinforce, at the passage\'s close, that penicillin\'s development depended on multiple distinct contributions rather than a single individual\'s work','Introduce new evidence that Fleming\'s original 1929 publication had been widely dismissed by the scientific community','Suggest that the Nobel committee initially intended to honor only Fleming before reconsidering','Establish that penicillin research continued for many additional decades after 1945'], answer:0, explanation:'This closing detail confirms the passage\'s central structural claim, set up in paragraph 3\'s contrast between what Fleming could and could not do and what Florey and Chain contributed — a shared prize is the natural capstone to an argument about distinct, complementary contributions. The "widely dismissed" choice invents a reception history the passage never describes; it says his attempts to interest chemists failed, which is different from the finding being publicly dismissed. The speculative Nobel-committee choice has no basis anywhere in the passage. And the sentence simply reports the prize awarded for the discovery already narrated — the passage says nothing about research continuing after 1945.' },
        { id:'rd20', topic:'Tone', stem:'How would you best describe the author\'s overall tone in narrating penicillin\'s development from paragraph 1 through paragraph 4?', options:['Measured and admiring, presenting the discovery and its development as a genuine scientific achievement without resorting to exaggeration','Skeptical, repeatedly questioning whether penicillin\'s benefits have been overstated','Nostalgic, primarily lamenting that modern medicine has lost the spirit of accidental discovery','Satirical, mocking the slow pace of scientific and industrial progress during this period'], answer:0, explanation:'Throughout, the author presents each step — accidental observation, purification breakthrough, wartime mass production — factually and with evident respect, as in noting a "transformation from laboratory curiosity to mass-produced medicine that took less than five years," without inserting exaggerated claims beyond what the facts support. The skeptical choice is unsupported; the passage reports "dramatic results" in human trials rather than casting doubt on them. The nostalgic choice invents a comparison to modern research culture that the passage never makes. And the satirical choice misreads the tone entirely — phrases like "urgent industrial priority" frame the wartime scale-up as impressively fast given the constraints, not as something to mock.' }
      ]
    }
  ],
  // Exam-only passages: held out from practice entirely, at real-exam density
  // (16-17 questions per passage, matching the OAT's 3-passage/50-question
  // Reading Comprehension section) so a timed test never recycles an item
  // the student has already seen with its explanation.
  examPassages: [
    {
      id: 'ep1',
      title: 'Passage V — The CRISPR Revolution',
      html: `
        <p><span class="pnum">[1]</span> In the late 1980s, researchers sequencing bacterial genomes noticed something strange: short, repeated DNA sequences, each reading almost the same forwards and backwards, separated by stretches of unique "spacer" DNA. For nearly two decades, the function of these repeats — later named CRISPR, for Clustered Regularly Interspaced Short Palindromic Repeats — remained a mystery. The turning point came when researchers compared the spacer sequences against public genetic databases and found that many of them matched the DNA of viruses known to infect bacteria, called bacteriophages. This was a striking clue: why would a bacterium carry fragments of its viral enemies' genetic code embedded in its own genome?</p>
        <p><span class="pnum">[2]</span> The answer, confirmed experimentally by 2007, is that CRISPR is an adaptive immune system. When a bacteriophage infects a bacterial cell, the bacterium can capture a short snippet of the invading virus's DNA and insert it as a new spacer into its own CRISPR array, alongside a growing library of past infections. If the same virus — or a close relative — attacks again, the bacterium transcribes its CRISPR array into RNA, which is processed into short guide RNAs. Each guide RNA partners with a CRISPR-associated protein, most famously one called Cas9, forming a complex that scans the cell's DNA for a sequence matching the guide. When it finds a match, Cas9 slices the invading DNA in two, neutralizing the infection. In effect, the bacterium has built itself a heritable, sequence-specific memory of every virus it has ever survived.</p>
        <p><span class="pnum">[3]</span> The insight that transformed CRISPR from a bacterial curiosity into one of the most consequential tools in modern biology came in 2012, when biochemists Jennifer Doudna and Emmanuelle Charpentier demonstrated that the guide RNA and Cas9 protein could be repurposed entirely. Because Cas9 will cut wherever its guide RNA tells it to, researchers could simply synthesize a guide RNA matching any DNA sequence of their choosing — in any organism, not just bacteria — and direct Cas9 to cut precisely there. Once Cas9 makes its cut, the cell's own DNA repair machinery takes over, and it does so in one of two ways: an error-prone pathway called non-homologous end joining, which often introduces small insertions or deletions that disable the gene entirely (a "knockout"), or, if scientists supply a DNA template alongside Cas9, a much more precise pathway called homology-directed repair, which can rewrite the sequence exactly as specified. Doudna and Charpentier were awarded the Nobel Prize in Chemistry in 2020 for this work.</p>
        <p><span class="pnum">[4]</span> The applications followed quickly. In agriculture, CRISPR allows breeders to disable or adjust a crop's own genes — producing, for example, mushrooms that resist browning or wheat with improved disease resistance — without inserting DNA from an unrelated species, the technique that defined earlier generations of genetically modified organisms. In medicine, the milestone arrived in December 2023, when regulators approved the first CRISPR-based therapy, a treatment for sickle cell disease and transfusion-dependent beta-thalassemia. The therapy works by removing a patient's own blood-forming stem cells, editing them outside the body to reactivate a form of hemoglobin normally switched off after infancy, and returning the corrected cells to the patient.</p>
        <p><span class="pnum">[5]</span> That sickle cell therapy illustrates a crucial distinction that runs through every discussion of CRISPR's future: the difference between somatic and germline editing. Somatic editing — altering genes in the non-reproductive cells of an already-living person, as the sickle cell therapy does — affects only that individual and is never passed to their children. Germline editing, by contrast, alters eggs, sperm, or early embryos, and any changes made become heritable, passed down to every subsequent generation. This distinction turned from an abstract ethical debate into an international controversy in 2018, when the Chinese scientist He Jiankui announced that he had edited human embryos — disabling a gene called CCR5 in an attempt to confer resistance to HIV — resulting in the birth of twin girls. The scientific community's reaction was swift and overwhelmingly critical, condemning the experiment as premature, medically unjustified, and conducted without adequate oversight; He was later sentenced to prison in China for illegal medical practice.</p>
        <p><span class="pnum">[6]</span> Even setting germline editing aside, CRISPR's precision is not absolute. A guide RNA can occasionally direct Cas9 to cut at an unintended location elsewhere in the genome that happens to share a similar sequence to the intended target — a phenomenon known as an off-target effect. Because an unwanted cut in the wrong gene could have serious consequences, refining guide RNA design and engineering more precise Cas variants remains an active area of research, and one that researchers generally regard as a prerequisite for any wider medical use of the technology beyond the carefully controlled, ex-vivo approach used in therapies like the sickle cell treatment.</p>
      `,
      questions: [
        { id:'rex1', topic:'Detail', stem:'According to the passage, what initially drew researchers\' attention to the function of CRISPR spacer sequences?', options:['The spacers were found to match the DNA of viruses known to infect bacteria','The spacers were found only in bacteria that had survived antibiotic exposure','The spacers were identical to sequences found in the human genome','The spacers appeared exclusively in bacteria grown in laboratory conditions'], answer:0, explanation:'Paragraph 1 states that researchers "compared the spacer sequences against public genetic databases and found that many of them matched the DNA of viruses known to infect bacteria, called bacteriophages." This match to viral DNA is what raised the question of why bacteria would carry fragments of viral genetic code, ultimately leading to the immune-system hypothesis. None of the other options — antibiotic survival, human genome matches, or a lab-only occurrence — are mentioned anywhere in the passage.' },
        { id:'rex2', topic:'Detail', stem:'Based on paragraph 2, what specifically happens when a bacterium survives a bacteriophage infection for the first time?', options:['It permanently loses the ability to be infected by any virus in the future','It captures a snippet of the virus\'s DNA and inserts it as a new spacer into its CRISPR array','It immediately produces Cas9 protein that destroys all viral particles in its environment','It transfers its CRISPR array to nearby uninfected bacteria to warn them'], answer:1, explanation:'Paragraph 2 states directly: "the bacterium can capture a short snippet of the invading virus\'s DNA and insert it as a new spacer into its own CRISPR array, alongside a growing library of past infections." This is the acquisition step of CRISPR immunity. The passage never claims permanent immunity to all viruses (only to matching ones, and only if the spacer is retained), never describes Cas9 as acting immediately upon first infection (the guide RNA/Cas9 response is described as the mechanism for defending against a repeat infection), and never mentions transferring the array to other bacteria.' },
        { id:'rex3', topic:'Detail', stem:'What role does the Cas9 protein play once a bacterium is reinfected by a virus it has previously encountered?', options:['It transcribes the CRISPR array into RNA for the first time', 'It partners with a guide RNA to locate and cut matching viral DNA', 'It synthesizes a new spacer sequence to add to the CRISPR array', 'It repairs the bacterium\'s own DNA after a viral attack'], answer:1, explanation:'Paragraph 2 explains that the guide RNA "partners with a CRISPR-associated protein, most famously one called Cas9, forming a complex that scans the cell\'s DNA for a sequence matching the guide," and when it finds a match, "Cas9 slices the invading DNA in two." Transcribing the array into RNA happens before Cas9 becomes involved (the guide RNA is a product of that transcription, not something Cas9 creates), spacer acquisition is a separate step described earlier in the paragraph, and DNA repair belongs to a different part of the passage entirely (paragraph 3, in the context of engineered CRISPR editing, not natural bacterial immunity).' },
        { id:'rex4', topic:'Main Idea', stem:'What is the primary purpose of paragraph 1?', options:['To explain how CRISPR is used as a modern gene-editing tool', 'To introduce the initial scientific puzzle that led to the discovery of CRISPR\'s natural function', 'To describe the ethical controversy surrounding CRISPR', 'To compare CRISPR to older genetic engineering techniques'], answer:1, explanation:'Paragraph 1 is entirely about the mystery phase of CRISPR research: researchers noticed the repeated sequences, didn\'t understand their function "for nearly two decades," and then found the clue (matching viral DNA) that eventually led to solving the puzzle. The gene-editing tool, the ethical controversy, and the comparison to older techniques are all covered in later paragraphs (3, 5, and 4 respectively) — paragraph 1\'s job is specifically to set up the original scientific question, not to answer it or extend it into any of those later topics.' },
        { id:'rex5', topic:'Main Idea', stem:'Which statement best captures the overall structure of the passage as a whole?', options:['It moves chronologically from CRISPR\'s discovery as a natural bacterial immune mechanism, through its repurposing as an editing tool, to its real-world applications and unresolved concerns', 'It presents two competing scientific theories about CRISPR and argues that one is correct', 'It focuses exclusively on the ethical controversy surrounding human embryo editing', 'It compares CRISPR unfavorably to earlier gene-editing technologies throughout'], answer:0, explanation:'The passage follows a clear chronological and conceptual arc: paragraph 1 introduces the original mystery, paragraph 2 explains the natural immune mechanism, paragraph 3 covers the 2012 breakthrough that turned it into an editing tool, paragraph 4 covers agricultural and medical applications, paragraph 5 covers the somatic/germline distinction and the He Jiankui controversy, and paragraph 6 covers the remaining technical limitation of off-target effects. It is not structured as a debate between competing theories, it discusses far more than just the embryo-editing controversy (which is confined mainly to paragraph 5), and it never argues CRISPR is inferior to older techniques — paragraph 4 actually highlights an advantage CRISPR has over them.' },
        { id:'rex6', topic:'Inference', stem:'Based on paragraph 3, what would most likely happen if researchers used Cas9 and a guide RNA to cut a gene, but did NOT supply any DNA template?', options:['The cell would be unable to repair the cut at all, and would die immediately', 'The cut would most likely be repaired by non-homologous end joining, likely disabling the gene', 'The cut would automatically be repaired with perfect precision by homology-directed repair', 'Cas9 would decline to make the cut in the first place without a template present'], answer:1, explanation:'Paragraph 3 explains that after Cas9 cuts, repair proceeds via one of two pathways: non-homologous end joining, which happens by default and "often introduces small insertions or deletions that disable the gene entirely," or homology-directed repair, which requires that "scientists supply a DNA template alongside Cas9." Without a supplied template, only the first pathway is available, making a gene-disabling outcome the most likely result. The passage gives no indication that a cut cell without a template simply dies, nor that Cas9 itself requires a template to function — the template requirement belongs to the repair step, not the cutting step.' },
        { id:'rex7', topic:'Inference', stem:'The passage most strongly suggests that the primary technical obstacle preventing CRISPR from being more widely used directly inside a living patient\'s body (rather than on cells removed and edited outside the body) is:', options:['The risk of off-target effects, in which Cas9 cuts unintended, similarly-sequenced locations in the genome', 'The fact that Cas9 cannot be synthesized in large enough quantities for medical use', 'The complete absence of any successful CRISPR-based medical therapy to date', 'Legal restrictions that make all forms of gene editing illegal worldwide'], answer:0, explanation:'Paragraph 6 identifies off-target effects as a real risk ("an unwanted cut in the wrong gene could have serious consequences") and states that addressing this "remains an active area of research, and one that researchers generally regard as a prerequisite for any wider medical use of the technology beyond the carefully controlled, ex-vivo approach" used in the sickle cell therapy. This directly implies that off-target risk is the obstacle standing between today\'s outside-the-body approach and broader in-body use. The passage never mentions any difficulty manufacturing Cas9, directly contradicts the idea that no therapy exists (paragraph 4 describes the approved sickle cell treatment), and never claims gene editing is illegal — it describes an approved, in-use therapy.' },
        { id:'rex8', topic:'Inference', stem:'Based on the passage, which of the following individuals would most likely have faced the most severe professional and legal consequences?', options:['Jennifer Doudna, for her 2012 work repurposing CRISPR', 'A researcher administering the approved sickle cell therapy to a consenting adult patient', 'He Jiankui, for his 2018 embryo-editing experiment', 'A crop scientist using CRISPR to develop disease-resistant wheat'], answer:2, explanation:'The passage states plainly that He Jiankui\'s germline embryo-editing experiment was met with an "overwhelmingly critical" reaction from the scientific community, was condemned as "premature, medically unjustified, and conducted without adequate oversight," and that "He was later sentenced to prison in China for illegal medical practice." No comparable professional or legal consequence is described for Doudna (who instead received a Nobel Prize), for administering an approved, regulator-sanctioned somatic therapy, or for agricultural crop editing — all three of the other options describe conduct the passage treats as legitimate, successful, or celebrated rather than punished.' },
        { id:'rex9', topic:'Inference', stem:'The passage implies that a key practical advantage of CRISPR-edited crops over earlier-generation genetically modified crops is that CRISPR-edited crops:', options:['Grow measurably faster than any earlier genetically modified crop', 'Do not require any DNA from an unrelated species to be inserted into the plant\'s genome', 'Are immune to all forms of plant disease without exception', 'Cost nothing to develop compared to older genetic engineering methods'], answer:1, explanation:'Paragraph 4 explains that CRISPR "allows breeders to disable or adjust a crop\'s own genes... without inserting DNA from an unrelated species, the technique that defined earlier generations of genetically modified organisms." This directly contrasts CRISPR\'s approach (editing existing genes in place) with the defining feature of older GMOs (inserting foreign DNA), implying this is a meaningful practical distinction. The passage never discusses growth speed, claims of total disease immunity, or development cost anywhere.' },
        { id:'rex10', topic:'Function', stem:'The author\'s discussion of the He Jiankui controversy in paragraph 5 functions primarily to:', options:['Illustrate the real-world stakes of the somatic/germline distinction just introduced, and show how that abstract distinction became a concrete international controversy', 'Prove that all forms of CRISPR-based gene editing, including the approved sickle cell therapy, are unethical', 'Argue that Chinese scientific institutions provide inadequate oversight compared to those in other countries', 'Suggest that CCR5 is an unimportant gene with no real biological function'], answer:0, explanation:'The paragraph opens by defining the somatic/germline distinction in the abstract, then states "this distinction turned from an abstract ethical debate into an international controversy in 2018" before describing He\'s experiment — directly signaling that the example exists to ground and illustrate the preceding conceptual point. The passage never suggests the approved somatic sickle cell therapy (described favorably in paragraph 4) is unethical — quite the opposite framing is used for germline versus somatic editing. It also never makes a general claim about Chinese institutions broadly, nor does it suggest CCR5 lacks biological function; He specifically targeted CCR5 because of its established role in HIV susceptibility.' },
        { id:'rex11', topic:'Function', stem:'Why does the author explain the natural bacterial immune function of CRISPR (paragraph 2) before describing its use as a gene-editing tool (paragraph 3)?', options:['Because the natural mechanism — a guide RNA directing a cutting protein to a specific DNA sequence — is the same basic system that was later repurposed for editing, so understanding it first makes the engineering breakthrough easier to follow', 'Because the natural immune function is more scientifically important than the editing application and deserves more emphasis', 'Because the two topics are unrelated and their order in the passage is arbitrary', 'Because paragraph 3 could not be understood without first learning about bacteriophages specifically'], answer:0, explanation:'Paragraph 3 explicitly builds on paragraph 2\'s mechanism, opening with how "the guide RNA and Cas9 protein could be repurposed entirely" and explaining that "Cas9 will cut wherever its guide RNA tells it to" — language that only makes sense once the reader already understands, from paragraph 2, that guide RNAs direct Cas9 to matching DNA sequences in the bacterium\'s natural immune response. The ordering is a deliberate scaffold, not an arbitrary one, and the passage never claims the natural function is more "important" than the editing application — both receive substantial, roughly comparable attention.' },
        { id:'rex12', topic:'Function', stem:'The author\'s mention of the 2020 Nobel Prize in Chemistry, at the end of paragraph 3, functions primarily to:', options:['Underscore the scientific significance of the 2012 discovery just described, marking it as a widely recognized turning point', 'Suggest that the Nobel committee played a direct role in developing the CRISPR technology itself', 'Introduce a new, previously unmentioned application of CRISPR technology', 'Imply that Doudna and Charpentier\'s work has since been scientifically discredited'], answer:0, explanation:'The Nobel Prize detail comes immediately after describing Doudna and Charpentier\'s foundational 2012 discovery, serving as external validation of just how significant that breakthrough was judged to be by the broader scientific community — a natural capstone to the paragraph\'s narrative, similar in function to how the earlier reading passage on penicillin used its Nobel Prize mention. It does not suggest the Nobel committee did any of the underlying research (they only recognize it), it introduces no new application (applications are covered afterward, in paragraph 4), and nothing in the passage suggests the work has been discredited — quite the opposite, given its described real-world medical and agricultural applications.' },
        { id:'rex13', topic:'Detail', stem:'According to paragraph 4, what specific medical condition(s) does the first approved CRISPR-based therapy treat?', options:['Sickle cell disease and transfusion-dependent beta-thalassemia', 'HIV infection exclusively', 'All inherited genetic disorders affecting blood cells', 'Bacterial infections resistant to antibiotics'], answer:0, explanation:'Paragraph 4 states plainly that the December 2023 approval was "for sickle cell disease and transfusion-dependent beta-thalassemia." HIV resistance is discussed elsewhere in the passage (paragraph 5), but only in the context of He Jiankui\'s unauthorized, condemned embryo experiment — not the approved therapy. The passage never claims the approved therapy treats "all" inherited blood disorders (only these two specific named conditions), and antibiotic-resistant bacterial infection is not mentioned as a target of any therapy in the passage.' },
        { id:'rex14', topic:'Detail', stem:'According to paragraph 4, how does the approved sickle cell therapy actually deliver its edited cells to the patient?', options:['Cas9 is injected directly into the patient\'s bloodstream while still inside the body', 'The patient\'s own stem cells are removed, edited outside the body, and then returned to the patient', 'A donor\'s stem cells are edited and transplanted into the patient in place of the patient\'s own cells', 'The patient\'s embryonic cells are edited before birth'], answer:1, explanation:'Paragraph 4 describes the process precisely: "removing a patient\'s own blood-forming stem cells, editing them outside the body... and returning the corrected cells to the patient." This is the ex-vivo (outside-the-body) approach that paragraph 6 later references directly. The therapy uses the patient\'s own cells, not a donor\'s, is not injected directly in-body, and has nothing to do with embryonic editing (which is discussed separately, and critically, in paragraph 5 regarding germline editing).' },
        { id:'rex15', topic:'Tone', stem:'How would you best characterize the author\'s tone when discussing CRISPR\'s medical and agricultural applications in paragraph 4, compared to the tone used when discussing the He Jiankui episode in paragraph 5?', options:['Paragraph 4 is measured and largely positive in describing legitimate, approved applications; paragraph 5 shifts to a more critical tone in describing widely condemned conduct', 'Both paragraphs maintain an identical, uniformly critical tone throughout', 'Paragraph 4 is highly skeptical of CRISPR\'s medical value, while paragraph 5 is entirely approving of He Jiankui\'s experiment', 'The author expresses no discernible difference in tone between the two paragraphs'], answer:0, explanation:'Paragraph 4 presents the agricultural and medical applications factually and favorably, describing an approved therapy that treats real disease without noting any controversy. Paragraph 5, by contrast, explicitly uses language like "overwhelmingly critical," "condemning the experiment as premature, medically unjustified, and conducted without adequate oversight," and notes He\'s prison sentence — a clear shift toward a critical, disapproving tone once the subject turns to unauthorized germline editing. This rules out both the "identical tone" option and, especially, the option reversing the two paragraphs\' actual tones.' },
        { id:'rex16', topic:'Detail', stem:'According to paragraph 6, what causes an "off-target effect" during CRISPR editing?', options:['A guide RNA directing Cas9 to cut at an unintended genomic location that happens to share a similar sequence to the actual target', 'Cas9 spontaneously cutting DNA at random locations with no relationship to the guide RNA at all', 'The DNA repair template being inserted into the wrong cell entirely', 'A patient\'s immune system rejecting the Cas9 protein after treatment'], answer:0, explanation:'Paragraph 6 defines the term directly: "a guide RNA can occasionally direct Cas9 to cut at an unintended location elsewhere in the genome that happens to share a similar sequence to the intended target — a phenomenon known as an off-target effect." The cutting is not random or unrelated to the guide RNA (it happens specifically because of an imperfect sequence match), and the passage never discusses immune rejection of Cas9 or template mis-delivery anywhere.' },
        { id:'rex17', topic:'Inference', stem:'Which statement would the author most likely agree with, based on the passage as a whole?', options:['CRISPR technology has produced both significant, responsibly-developed medical benefits and serious ethical controversies, and technical challenges to its use remain unresolved', 'CRISPR technology has been an unqualified success story with no remaining risks or controversies of any kind', 'CRISPR technology has so far failed to produce any practical real-world applications', 'The scientific community has reached a consensus that all forms of gene editing, including the approved sickle cell therapy, should be banned'], answer:0, explanation:'The passage as a whole presents a balanced picture: real, approved medical benefits (paragraph 4), a serious and widely condemned ethical breach (paragraph 5), and an acknowledged, unresolved technical limitation (paragraph 6, off-target effects). This rules out the "unqualified success" option (which ignores paragraphs 5 and 6) and the "no practical applications" option (which ignores paragraph 4\'s approved therapy and agricultural uses). Nothing in the passage suggests the scientific community opposes the approved somatic therapy — the criticism throughout is specifically directed at unauthorized germline editing, not at CRISPR-based medicine in general.' }
      ]
    },
    {
      id: 'ep2',
      title: 'Passage VI — The Ozone Layer: Depletion and Recovery',
      html: `
        <p><span class="pnum">[1]</span> High in Earth's stratosphere, roughly 15 to 35 kilometers above the surface, a diffuse layer of ozone (O₃) molecules absorbs the great majority of the sun's ultraviolet-B (UV-B) radiation before it reaches the ground. Without this shielding, UV-B levels at the surface would rise sharply, damaging DNA in living cells and significantly increasing rates of skin cancer, cataracts, and harm to crops and marine ecosystems. Ozone is created and destroyed continuously by natural processes in the stratosphere, and for most of Earth's history this cycle remained in a rough, self-sustaining balance.</p>
        <p><span class="pnum">[2]</span> That balance came under threat from an unexpected source. In 1974, chemists Mario Molina and F. Sherwood Rowland published a hypothesis proposing that chlorofluorocarbons, or CFCs — synthetic compounds then in widespread use as refrigerants, aerosol propellants, and foam-blowing agents, prized for being non-flammable and chemically stable — could rise slowly into the stratosphere over a period of years. There, intense ultraviolet radiation would break the CFC molecules apart, releasing free chlorine atoms. Each of these chlorine atoms could then destroy ozone catalytically: a single chlorine atom could break apart thousands of ozone molecules in a repeating reaction cycle, since the chlorine itself was regenerated at the end of each cycle rather than being consumed by it. At the time, the hypothesis was met with considerable skepticism, and manufacturers of CFCs largely dismissed the proposed threat as speculative.</p>
        <p><span class="pnum">[3]</span> That skepticism became far harder to sustain in 1985, when scientists with the British Antarctic Survey, led by Joseph Farman, published direct atmospheric measurements showing a dramatic seasonal thinning of ozone over Antarctica each spring — a depletion so severe that it soon became known as the "ozone hole." The scale of the loss exceeded what existing computer models based on Molina and Rowland's chemistry alone had predicted, and it took further research to explain why: the extreme cold of the Antarctic winter allows unusual polar stratospheric clouds to form, and an isolated pattern of circulating winds called the polar vortex traps and concentrates chlorine compounds over the continent, dramatically accelerating the catalytic destruction of ozone once sunlight returns each spring.</p>
        <p><span class="pnum">[4]</span> The Antarctic findings galvanized international action. In 1987, nations negotiated the Montreal Protocol, a treaty committing signatories to phase out the production and use of CFCs and related ozone-depleting substances on a defined timeline. Unlike many international environmental agreements, the Montreal Protocol achieved universal ratification — every member state of the United Nations eventually became a party to it — and is frequently cited by policy researchers as one of the most successful environmental treaties ever negotiated, notable both for the speed with which scientific findings were translated into binding international policy and for the willingness of industry to develop and adopt substitute chemicals.</p>
        <p><span class="pnum">[5]</span> Recovery, however, has been gradual rather than immediate. Because CFCs and related compounds persist in the atmosphere for decades after their release, the ozone layer could not simply snap back to its earlier state once emissions declined. The Antarctic ozone hole still forms each austral spring, though monitoring data show it has been shrinking over time, and current atmospheric models project that ozone concentrations over most of the globe will return to pre-1980 levels sometime around the 2060s, with full recovery over Antarctica itself, where depletion has been most severe, expected somewhat later still.</p>
        <p><span class="pnum">[6]</span> The ozone story is now commonly invoked, particularly in discussions of other global environmental challenges, as a rare example of a worldwide environmental problem being identified, understood, and substantially addressed within a single human generation. Commentators frequently draw a contrast between the relatively swift path from initial scientific hypothesis (1974) to binding international treaty (1987) in the ozone case, and the considerably slower, more contested international response to other atmospheric challenges identified around the same era — a comparison usually intended to illustrate what coordinated global action can accomplish, rather than to suggest the two problems were equally simple to solve.</p>
      `,
      questions: [
        { id:'rex18', topic:'Detail', stem:'According to paragraph 1, what is the primary function of stratospheric ozone described in the passage?', options:['It absorbs most of the sun\'s ultraviolet-B radiation before it reaches Earth\'s surface', 'It regulates global temperatures by trapping heat in the atmosphere', 'It produces the oxygen that living organisms breathe', 'It reflects visible sunlight back into space'], answer:0, explanation:'Paragraph 1 states that ozone "absorbs the great majority of the sun\'s ultraviolet-B (UV-B) radiation before it reaches the ground," and that without it, "UV-B levels at the surface would rise sharply, damaging DNA in living cells." The passage never describes ozone as trapping heat (a description more associated with greenhouse gases generally, not ozone\'s role here), never claims it produces breathable oxygen, and never mentions it reflecting visible light.' },
        { id:'rex19', topic:'Detail', stem:'According to paragraph 2, why were CFCs so widely used before their environmental effects were understood?', options:['They were inexpensive to manufacture compared to all available alternatives', 'They were non-flammable and chemically stable, useful properties for refrigerants, propellants, and foam-blowing agents', 'They were required by international regulations at the time', 'They were byproducts of an unrelated industrial process and were otherwise difficult to dispose of'], answer:1, explanation:'Paragraph 2 states that CFCs were "prized for being non-flammable and chemically stable" in their roles "as refrigerants, aerosol propellants, and foam-blowing agents." Cost is never discussed, no regulation requiring their use is mentioned, and the passage never describes them as an unwanted industrial byproduct — they were manufactured deliberately for these specific, valued properties.' },
        { id:'rex20', topic:'Detail', stem:'According to paragraph 2, why is a single chlorine atom released from a CFC molecule capable of destroying thousands of ozone molecules?', options:['The chlorine atom is regenerated at the end of each reaction cycle, allowing it to repeat the destructive process many times', 'Each chlorine atom releases thousands of additional chlorine atoms when it reacts', 'Chlorine atoms are far larger than ozone molecules and destroy several at once through direct collision', 'Ultraviolet radiation multiplies the number of chlorine atoms present in the stratosphere over time'], answer:0, explanation:'Paragraph 2 explains that chlorine destroys ozone "catalytically," meaning "a single chlorine atom could break apart thousands of ozone molecules in a repeating reaction cycle, since the chlorine itself was regenerated at the end of each cycle rather than being consumed by it." The passage never describes chlorine atoms multiplying, colliding physically with multiple ozone molecules, or being created by UV radiation — UV radiation\'s described role is breaking apart the original CFC molecule, not generating more chlorine.' },
        { id:'rex21', topic:'Detail', stem:'According to paragraph 3, what specific atmospheric conditions over Antarctica help explain why ozone depletion there was more severe than initial models predicted?', options:['Unusually high stratospheric temperatures that accelerate chemical reactions', 'The extreme cold enabling polar stratospheric clouds to form, combined with a polar vortex that traps and concentrates chlorine compounds', 'The complete absence of any wind patterns over the Antarctic continent', 'Antarctica\'s unusually high elevation, which brings it physically closer to the ozone layer'], answer:1, explanation:'Paragraph 3 attributes the severity to two specific factors: "the extreme cold of the Antarctic winter allows unusual polar stratospheric clouds to form, and an isolated pattern of circulating winds called the polar vortex traps and concentrates chlorine compounds over the continent." This directly contradicts the "high temperatures" option (the passage specifies extreme cold, not heat) and the "no wind patterns" option (the polar vortex is itself a wind pattern, not an absence of one). Antarctica\'s elevation relative to the stratosphere is never mentioned as a factor.' },
        { id:'rex22', topic:'Detail', stem:'According to paragraph 4, what made the Montreal Protocol unusual compared to many other international environmental agreements?', options:['It achieved universal ratification by every UN member state', 'It was the first environmental treaty ever negotiated between any two nations', 'It imposed no specific timeline for phasing out the chemicals it targeted', 'It was opposed by the chemical industry throughout its implementation'], answer:0, explanation:'Paragraph 4 states that "Unlike many international environmental agreements, the Montreal Protocol achieved universal ratification — every member state of the United Nations eventually became a party to it." The passage never claims it was the first environmental treaty of any kind (only that it stands out among such treaties), explicitly says it committed signatories to "a defined timeline" (not the absence of one), and describes industry as developing and adopting substitute chemicals rather than opposing the treaty\'s implementation.' },
        { id:'rex23', topic:'Detail', stem:'According to paragraph 5, why hasn\'t the ozone layer recovered immediately since CFC production was phased out?', options:['CFCs and related compounds persist in the atmosphere for decades after release', 'Scientists have been unable to develop reliable methods for monitoring atmospheric ozone levels', 'The Montreal Protocol has not yet been fully implemented by most signatory nations', 'Natural ozone production has permanently declined for reasons unrelated to CFCs'], answer:0, explanation:'Paragraph 5 states directly: "Because CFCs and related compounds persist in the atmosphere for decades after their release, the ozone layer could not simply snap back to its earlier state once emissions declined." The passage does not question the reliability of ozone monitoring (it cites "monitoring data" as a source of evidence), does not suggest incomplete implementation of the treaty, and never attributes any decline to a cause unrelated to CFCs.' },
        { id:'rex24', topic:'Main Idea', stem:'What is the primary purpose of the passage as a whole?', options:['To trace the ozone depletion problem from its scientific discovery through international response to its still-ongoing recovery', 'To argue that the Montreal Protocol was ultimately an ineffective response to ozone depletion', 'To provide a detailed technical explanation of atmospheric chemistry unrelated to any policy history', 'To compare the economic costs borne by different industries in complying with the Montreal Protocol'], answer:0, explanation:'The passage moves through a clear arc: paragraph 1 establishes why ozone matters, paragraph 2 introduces the CFC hypothesis, paragraph 3 covers the Antarctic discovery that confirmed and dramatized the threat, paragraph 4 covers the international treaty response, paragraph 5 covers the ongoing, gradual recovery, and paragraph 6 reflects on the episode\'s broader significance. The passage explicitly frames the Montreal Protocol as "one of the most successful environmental treaties ever negotiated," the opposite of arguing it was ineffective. It combines chemistry with policy and history throughout rather than isolating pure atmospheric science, and it never compares specific costs across industries.' },
        { id:'rex25', topic:'Main Idea', stem:'Which best describes the relationship between paragraphs 2 and 3?', options:['Paragraph 2 introduces a scientific hypothesis that was initially doubted; paragraph 3 describes the observational evidence that made the hypothesis far more difficult to dismiss', 'Paragraph 2 and paragraph 3 present two competing, mutually exclusive explanations for ozone depletion', 'Paragraph 3 describes events that occurred chronologically before the events described in paragraph 2', 'Paragraph 3 contradicts and ultimately disproves the hypothesis introduced in paragraph 2'], answer:0, explanation:'Paragraph 2 introduces the 1974 Molina-Rowland hypothesis and notes it "was met with considerable skepticism." Paragraph 3 then describes 1985 measurements over Antarctica that made "that skepticism... far harder to sustain," directly building on and reinforcing (not contradicting or chronologically preceding) the earlier hypothesis. The two paragraphs are not competing explanations — paragraph 3\'s Antarctic findings are explicitly framed as confirming and extending the chemistry paragraph 2 already introduced, once the additional factors of polar clouds and the polar vortex are accounted for.' },
        { id:'rex26', topic:'Inference', stem:'Based on paragraph 2, what can be inferred about why CFCs were not recognized as an environmental threat before 1974?', options:['Their valued properties (non-flammability, chemical stability) were the same properties that allowed them to persist long enough to reach and accumulate in the stratosphere, a slow, indirect process not obviously connected to their everyday uses', 'CFCs had only recently been invented and had not yet been widely manufactured by 1974', 'Scientists had tested CFCs for atmospheric effects and initially concluded they were completely harmless', 'CFCs were kept as a closely guarded industrial secret prior to 1974'], answer:0, explanation:'Paragraph 2 describes CFCs as "chemically stable" — precisely the property that let them "rise slowly into the stratosphere over a period of years" before breaking apart, a process disconnected in time and location from their ordinary use in refrigerators or aerosol cans. This supports the inference that the very stability making them useful also made their eventual atmospheric effect non-obvious and delayed. The passage says nothing about CFCs being newly invented in 1974, doesn\'t describe any prior scientific testing having declared them harmless, and never suggests they were a secret.' },
        { id:'rex27', topic:'Inference', stem:'The passage most strongly suggests that if Molina and Rowland\'s original 1974 models had already accounted for the polar vortex and polar stratospheric clouds described in paragraph 3, which of the following would most likely have occurred?', options:['Their models would likely have predicted more severe ozone depletion over Antarctica specifically, rather than underestimating it as the actual 1974 models did', 'CFCs would not have been identified as a threat to the ozone layer at all', 'The Montreal Protocol would have been unnecessary', 'Ozone depletion would have been observed at the North Pole instead of the South Pole'], answer:0, explanation:'Paragraph 3 states that the actual scale of Antarctic ozone loss "exceeded what existing computer models based on Molina and Rowland\'s chemistry alone had predicted," and that additional factors (polar stratospheric clouds, the polar vortex) were needed to explain the discrepancy. This implies that incorporating those factors from the start would have produced a more accurate — and more severe — prediction specifically for Antarctica, not a reversal of the CFC hypothesis itself, and not a conclusion that the treaty was unneeded. The passage attributes the dramatic depletion specifically to conditions "over Antarctica," giving no basis for inferring a similar outcome at the North Pole instead.' },
        { id:'rex28', topic:'Inference', stem:'Based on paragraph 5, what does the passage imply about the relationship between the timing of the Montreal Protocol\'s emission cuts and the timing of the ozone layer\'s full recovery?', options:['There is a significant time lag between reducing emissions and achieving full recovery, due to the multi-decade atmospheric persistence of the responsible chemicals', 'Full recovery occurred almost immediately after the Montreal Protocol took effect in 1987', 'The ozone layer will never fully recover regardless of how long emissions remain reduced', 'Recovery timing depends entirely on future policy decisions rather than on any chemical or atmospheric process'], answer:0, explanation:'Paragraph 5 directly links the multi-decade persistence of CFCs to the fact that recovery "could not simply snap back," and projects recovery timelines extending to "sometime around the 2060s" for most of the globe — roughly 80 years after the 1974 hypothesis and about 75 years after the 1987 treaty. This is a substantial gap that the passage attributes specifically to atmospheric persistence, contradicting both the "almost immediate" and "never fully recover" options; the passage gives no indication that this projected recovery depends on any further policy decisions, since the projection is based on the chemistry already set in motion by emissions that have already been cut.' },
        { id:'rex29', topic:'Inference', stem:'Which of the following, if true, would most directly undermine the "coordinated global action" lesson that paragraph 6 says commentators typically draw from the ozone story?', options:['Evidence that the Montreal Protocol\'s ratification and emission cuts had little actual causal effect on the ozone layer\'s eventual recovery', 'Evidence that CFCs were more expensive to replace than initially anticipated', 'Evidence that the Antarctic ozone hole is larger in some years than in others', 'Evidence that other atmospheric gases also affect stratospheric chemistry'], answer:0, explanation:'Paragraph 6 frames the ozone story as illustrating "what coordinated global action can accomplish" — an argument that depends on the treaty and resulting emission cuts having actually caused the observed and projected recovery. If evidence showed the Protocol had little real causal effect on recovery (for instance, if some unrelated factor were actually responsible), the central lesson commentators draw would be undermined at its root. Cost overruns, year-to-year variation in the ozone hole\'s size, or the existence of other relevant atmospheric gases are all details that could be true without threatening the basic causal claim that international action reduced CFCs and thereby set recovery in motion.' },
        { id:'rex30', topic:'Function', stem:'The author\'s comparison, in paragraph 6, between the ozone response and the response to "other atmospheric challenges identified around the same era" functions primarily to:', options:['Illustrate how the ozone story is typically used as a point of contrast in broader discussions, while explicitly cautioning against over-generalizing from that comparison', 'Argue directly that all other global environmental problems are less scientifically valid than ozone depletion', 'Prove that international treaties are always the fastest possible solution to any environmental problem', 'Introduce a wholly new topic that is unrelated to the rest of the passage'], answer:0, explanation:'The sentence explicitly frames this as something "commentators frequently draw," not a claim the author is independently asserting, and it closes with an explicit caveat: the comparison is "usually intended to illustrate what coordinated global action can accomplish, rather than to suggest the two problems were equally simple to solve." This hedged, attributed framing is very different from the author personally arguing that other problems are less valid, and it stops well short of claiming treaties are always the fastest solution to everything. Far from introducing an unrelated topic, the comparison directly extends paragraph 4\'s point about the treaty\'s notable speed by placing it in a broader context.' },
        { id:'rex31', topic:'Function', stem:'Why does the author specify, in paragraph 2, that a single chlorine atom "could be regenerated at the end of each reaction cycle rather than being consumed by it"?', options:['To explain the specific chemical mechanism that allows one chlorine atom to cause disproportionately large ozone destruction over time', 'To argue that chlorine atoms are ultimately harmless because they are never permanently lost from the atmosphere', 'To suggest that ozone depletion is a naturally occurring, unavoidable process independent of CFCs', 'To introduce an unrelated side note about general chemical reaction theory'], answer:0, explanation:'This detail directly explains the sentence it follows — that "a single chlorine atom could break apart thousands of ozone molecules" — by clarifying the specific mechanism (catalysis) that makes that outsized destructive capacity possible. It is not used to argue chlorine is harmless (the entire point is the opposite: its persistence makes it more dangerous, not less), it says nothing about depletion being unavoidable or natural (the passage\'s whole premise is that CFCs are a synthetic, human-introduced cause), and it is tightly connected to the ozone-destruction discussion rather than being a tangent.' },
        { id:'rex32', topic:'Tone', stem:'How would you best describe the author\'s tone when describing the Montreal Protocol in paragraph 4?', options:['Approving, characterizing the treaty as a notably successful and swift example of international cooperation', 'Dismissive, suggesting the treaty accomplished little of lasting significance', 'Neutral to the point of declining to offer any assessment of the treaty\'s effectiveness', 'Alarmed, warning that the treaty\'s targets are unlikely to ever be met'], answer:0, explanation:'The paragraph directly states that the treaty is "frequently cited by policy researchers as one of the most successful environmental treaties ever negotiated" and highlights both "the speed with which scientific findings were translated into binding international policy" and industry\'s willingness "to develop and adopt substitute chemicals" — language that is clearly approving rather than neutral, dismissive, or alarmed. This is not a case of the author declining to assess the treaty; a specific, positive assessment is offered and attributed to policy researchers as a field-wide view.' }
      ]
    },
    {
      id: 'ep3',
      title: 'Passage VII — GPS and the Physics of Time',
      html: `
        <p><span class="pnum">[1]</span> The Global Positioning System relies on a constellation of satellites, each orbiting Earth while continuously broadcasting a signal stamped with the precise time it was sent, as measured by an atomic clock carried on board. A receiver on the ground — inside a phone, a car, or a handheld unit — picks up signals from several satellites simultaneously and compares their arrival times. Because radio signals travel at the constant, known speed of light, even a tiny difference in how long a signal took to arrive from each satellite can be converted into a precise distance to that satellite. Combining distance estimates from at least four satellites at once, a technique called trilateration, allows the receiver to calculate its own position on Earth's surface.</p>
        <p><span class="pnum">[2]</span> This method places extraordinary demands on timekeeping precision. Light travels at roughly 300,000 kilometers per second, so a timing error of just one microsecond — one-millionth of a second — translates into a position error of about 300 meters. To achieve the few-meter accuracy that GPS users have come to expect, the atomic clocks aboard each satellite must remain synchronized with clocks on the ground to within a matter of tens of nanoseconds, a level of precision almost impossible to appreciate in ordinary daily experience.</p>
        <p><span class="pnum">[3]</span> At this level of precision, effects predicted by Einstein's theories of relativity — effects far too small to notice in everyday life — become significant. Special relativity predicts that a clock moving at high speed relative to an observer will, from that observer's perspective, tick more slowly than an identical clock at rest. GPS satellites orbit at roughly 14,000 kilometers per hour, and as a consequence of this motion alone, their onboard clocks run slower than identical clocks on the ground by about 7 microseconds every day.</p>
        <p><span class="pnum">[4]</span> Working in the opposite direction is an effect predicted by general relativity: a clock in a weaker gravitational field ticks faster than an identical clock located deeper within a gravitational well. GPS satellites orbit at an altitude of roughly 20,200 kilometers, far enough from Earth's surface that they experience noticeably weaker gravity than clocks at ground level. This gravitational effect causes the satellites' clocks to run faster than ground clocks by about 45 microseconds per day — a larger effect, in the opposite direction, than the special-relativistic slowing described in paragraph 3.</p>
        <p><span class="pnum">[5]</span> Combining both effects, a GPS satellite's onboard clock runs fast overall by about 38 microseconds each day relative to a clock on the ground (45 microseconds gained from weaker gravity, minus 7 microseconds lost to orbital speed). Rather than correcting for this drift after the fact, engineers compensate for it in advance: before launch, each satellite's atomic clock is deliberately manufactured to tick very slightly slower than a standard ground-based clock, calibrated so that once the satellite reaches orbit, the combined relativistic effects bring its tick rate back into agreement with clocks on Earth's surface.</p>
        <p><span class="pnum">[6]</span> The stakes of this correction are considerable. Left uncorrected, the roughly 38-microsecond daily drift would compound into positioning errors of approximately 10 kilometers per day, an error that would grow without bound and would render the system essentially useless for navigation within hours of a satellite reaching orbit. For this reason, GPS is frequently cited as one of the first everyday technologies whose basic function depends on explicitly accounting for relativistic effects — effects that remain utterly negligible at the speeds and altitudes of ordinary experience, but that become unavoidable once a technology requires the level of timing precision GPS does.</p>
      `,
      questions: [
        { id:'rex33', topic:'Detail', stem:'According to paragraph 1, how does a GPS receiver determine the distance to a given satellite?', options:['By comparing how long the satellite\'s time-stamped signal took to arrive, using the known, constant speed at which the signal travels', 'By directly measuring the satellite\'s orbital altitude using an onboard sensor', 'By receiving a distance measurement calculated by the satellite itself and transmitted to the receiver', 'By comparing the relative brightness of signals from different satellites'], answer:0, explanation:'Paragraph 1 explains that a receiver "compares their arrival times," and because "radio signals travel at the constant, known speed of light, even a tiny difference in how long a signal took to arrive... can be converted into a precise distance." The satellite does not calculate or transmit a distance value itself, no altitude-sensing is described, and signal brightness/strength is never mentioned as part of the method — timing is the entire basis of the calculation described.' },
        { id:'rex34', topic:'Detail', stem:'According to paragraph 2, what position error would result from a timing error of one microsecond?', options:['About 300 meters', 'About 300 kilometers', 'About 3 meters', 'About 1 kilometer'], answer:0, explanation:'Paragraph 2 states this relationship directly: "a timing error of just one microsecond... translates into a position error of about 300 meters." This single stated figure is the basis for the paragraph\'s broader point about why extremely precise clock synchronization (to within tens of nanoseconds) is required to achieve GPS\'s typical few-meter accuracy — a nanosecond-scale requirement is a very different, far more demanding standard than a microsecond-scale one.' },
        { id:'rex35', topic:'Detail', stem:'According to paragraph 3, what does special relativity predict about a clock that is moving at high speed relative to an observer?', options:['It will tick more slowly, from that observer\'s perspective, than an identical clock at rest', 'It will tick more quickly, from that observer\'s perspective, than an identical clock at rest', 'It will tick at exactly the same rate as an identical clock at rest, with no measurable difference', 'It will stop ticking entirely once it exceeds a certain speed'], answer:0, explanation:'Paragraph 3 states plainly that "a clock moving at high speed relative to an observer will, from that observer\'s perspective, tick more slowly than an identical clock at rest," and applies this directly to GPS satellites, whose clocks "run slower than identical clocks on the ground by about 7 microseconds every day" due to their orbital speed. The passage explicitly quantifies a real, measurable difference (ruling out the "exactly the same rate" option) and never suggests clocks stop functioning at high speed.' },
        { id:'rex36', topic:'Detail', stem:'According to paragraph 4, why do GPS satellite clocks run faster than clocks on the ground, considered in isolation from the effect of orbital speed?', options:['Because they experience weaker gravity at their high altitude than clocks do at Earth\'s surface', 'Because they are exposed to more direct sunlight than ground-based clocks', 'Because they are manufactured using more advanced atomic clock technology than ground clocks', 'Because the vacuum of space contains no air resistance to slow the clock\'s mechanism'], answer:0, explanation:'Paragraph 4 attributes this specifically to general relativity: "a clock in a weaker gravitational field ticks faster than an identical clock located deeper within a gravitational well," and notes the satellites, at their high altitude, "experience noticeably weaker gravity than clocks at ground level." Sunlight exposure, superior manufacturing, and the absence of air resistance are never mentioned anywhere in the passage as explanations for either relativistic effect described.' },
        { id:'rex37', topic:'Detail', stem:'According to paragraph 5, how do engineers address the combined relativistic drift affecting GPS satellite clocks?', options:['They deliberately manufacture each satellite\'s clock to tick slightly slower than a standard ground clock before launch, anticipating that orbital effects will bring it back into agreement once in orbit', 'They replace each satellite\'s clock with a new one every 38 days to prevent excessive drift from accumulating', 'They rely entirely on ground-based receivers to mathematically correct for all timing errors after signals are received', 'They intentionally slow the satellites\' orbital speed to eliminate the special-relativistic effect entirely'], answer:0, explanation:'Paragraph 5 describes a pre-launch correction: "each satellite\'s atomic clock is deliberately manufactured to tick very slightly slower than a standard ground-based clock, calibrated so that once the satellite reaches orbit, the combined relativistic effects bring its tick rate back into agreement with clocks on Earth\'s surface." This is a proactive, built-in correction rather than a post-reception mathematical fix, a periodic clock replacement schedule, or a deliberate slowing of orbital speed — none of which the passage mentions.' },
        { id:'rex38', topic:'Main Idea', stem:'What is the primary purpose of the passage as a whole?', options:['To explain how GPS works and why it requires correcting for relativistic effects that are normally far too small to notice', 'To argue that GPS technology is fundamentally too imprecise to be relied upon for navigation', 'To provide a comprehensive history of the development and launch of the GPS satellite system', 'To compare GPS accuracy unfavorably against older, ground-based navigation technologies'], answer:0, explanation:'The passage builds a single explanatory chain: paragraph 1 explains the basic trilateration method, paragraph 2 establishes why extreme timing precision matters, paragraphs 3 and 4 introduce the two competing relativistic effects, paragraph 5 explains how engineers correct for them, and paragraph 6 explains the consequences of not doing so. Far from arguing GPS is too imprecise, the passage explains how the system achieves precise, reliable accuracy specifically by accounting for relativity. No history of the system\'s development or launch is given, and no comparison to older navigation technologies is made anywhere.' },
        { id:'rex39', topic:'Main Idea', stem:'Which best summarizes the relationship between the effects described in paragraphs 3 and 4?', options:['They act in opposite directions on the satellite clocks\' tick rate, with the gravitational effect in paragraph 4 being the larger of the two', 'They act in the same direction, both slowing the satellite clocks by an identical amount', 'The effect in paragraph 4 was later shown to disprove the effect described in paragraph 3', 'The two effects apply only to ground-based clocks, not to the satellites themselves'], answer:0, explanation:'Paragraph 4 explicitly describes its gravitational effect as acting "in the opposite direction" to the speed-based slowing from paragraph 3, and specifies it is "a larger effect... than the special-relativistic slowing described in paragraph 3" (45 microseconds/day gained vs. 7 microseconds/day lost). The two effects are not identical in direction or magnitude, neither disproves the other — both are combined together in paragraph 5\'s net calculation — and both effects are described as applying to the satellites\' clocks, not to clocks on the ground.' },
        { id:'rex40', topic:'Inference', stem:'Based on paragraph 6, what can be inferred about the size of GPS positioning errors if the relativistic correction described in paragraph 5 were removed and no other correction were applied?', options:['The errors would grow larger with each passing day, rather than stabilizing at a fixed, constant size', 'The errors would remain fixed at exactly 300 meters indefinitely', 'The system would continue to function with only a minor, one-time loss of accuracy', 'The satellites themselves would physically fall out of orbit'], answer:0, explanation:'Paragraph 6 describes the uncorrected drift as compounding "into positioning errors of approximately 10 kilometers per day, an error that would grow without bound" — language that directly indicates an accumulating, ever-increasing error over time rather than a fixed, one-time, or stabilized amount. The passage never suggests any physical effect on the satellites\' orbits themselves; the consequence described is entirely about the accuracy of position calculations on the ground, not the stability of the satellites\' physical trajectories.' },
        { id:'rex41', topic:'Inference', stem:'The passage most strongly suggests that if GPS satellites orbited at a much lower altitude than 20,200 kilometers — while maintaining the same orbital speed — which of the following would most likely occur?', options:['The gravitational (general-relativistic) effect described in paragraph 4 would be smaller, since gravity would be less weak relative to Earth\'s surface at a lower altitude', 'The gravitational effect would disappear entirely, leaving only the special-relativistic effect from paragraph 3', 'Both relativistic effects described in the passage would be eliminated entirely', 'The special-relativistic effect from orbital speed would become stronger as a direct result of the lower altitude'], answer:0, explanation:'Paragraph 4 ties the size of the gravitational time-dilation effect directly to how much weaker gravity is at the satellite\'s altitude compared to the surface — "a clock in a weaker gravitational field ticks faster," and a lower altitude means a stronger (less weak) local gravitational field, closer to that of the surface. This implies a smaller gravitational effect at lower altitude, not its complete disappearance. The special-relativistic effect from paragraph 3 depends on orbital speed specifically, which the question specifies is held constant, so altitude alone would not be expected to change that separate effect.' },
        { id:'rex42', topic:'Inference', stem:'Based on the passage, which of the following technologies would most plausibly require accounting for relativistic timing effects similar to those described for GPS?', options:['A hypothetical navigation satellite system requiring similarly precise timing synchronization between fast-moving, high-altitude satellites and ground receivers', 'A standard kitchen clock used to time a recipe to the nearest minute', 'A car\'s speedometer, which measures speed directly rather than relying on timed signals', 'A wall calendar used to track the days of the month'], answer:0, explanation:'The passage\'s central point, especially in paragraph 6, is that relativistic effects become significant specifically when a technology depends on extremely precise timing combined with high speed and/or significant altitude differences — exactly the conditions described for GPS. A hypothetical system sharing those same core features (fast-moving, high-altitude, timing-dependent) would plausibly face the same issue. A kitchen clock, a speedometer, and a calendar all operate at precision levels (minutes, direct measurement, or days) vastly coarser than the nanosecond-scale requirements the passage describes as the actual source of the problem.' },
        { id:'rex43', topic:'Function', stem:'Why does the author include the specific figure "about 300 meters" in paragraph 2?', options:['To make concrete, using a familiar unit of distance, just how large an error results from an extremely small timing mistake — motivating why such precise clock synchronization is necessary', 'To state the maximum possible accuracy that GPS technology could ever theoretically achieve', 'To provide the exact orbital altitude at which GPS satellites travel', 'To contradict the level of precision claimed elsewhere in the passage'], answer:0, explanation:'This figure directly follows the statement that "a timing error of just one microsecond... translates into a position error of about 300 meters," using a distance most readers can easily picture to dramatize how disproportionately large a positioning error results from an almost imperceptibly small timing error — setting up the paragraph\'s conclusion that clocks must be synchronized "to within a matter of tens of nanoseconds." It is not presented as GPS\'s best-case accuracy (which the passage separately describes as "a few meters"), has nothing to do with orbital altitude (a distinct figure given later, in paragraph 4), and is entirely consistent with, not contradictory to, the rest of the passage.' },
        { id:'rex44', topic:'Function', stem:'What is the primary function of paragraph 6 within the overall structure of the passage?', options:['It explains the practical consequences that would follow if the relativistic correction described in paragraph 5 were not applied, reinforcing why that correction matters', 'It introduces an entirely new, previously undiscussed scientific concept unrelated to timing or relativity', 'It presents evidence that ultimately disproves the relativistic effects described earlier in the passage', 'It shifts the passage\'s focus away from GPS toward a general history of satellite technology'], answer:0, explanation:'Paragraph 6 picks up directly from paragraph 5\'s description of the pre-launch correction, describing what would happen "left uncorrected" — namely, errors "growing without bound" and the system becoming "essentially useless... within hours." This directly reinforces, rather than introduces something separate from, the stakes of the correction just described. It does not challenge or disprove anything from earlier paragraphs (it assumes the same relativistic effects are real and significant), and it stays tightly focused on GPS\'s dependence on relativistic correction rather than pivoting to unrelated satellite history.' },
        { id:'rex45', topic:'Tone', stem:'How would you best describe the author\'s overall tone throughout the passage?', options:['Informative and explanatory, presenting a chain of scientific cause and effect without expressing skepticism or alarm about GPS\'s reliability', 'Skeptical, repeatedly questioning whether relativistic effects are real', 'Alarmed, warning readers that GPS devices are currently unreliable for everyday use', 'Sarcastic, mocking the complexity of the engineering solutions described'], answer:0, explanation:'Throughout, the passage presents each step — the trilateration method, the precision requirement, the two relativistic effects, the correction, and its consequences if omitted — as established, factual cause and effect, without hedging language suggesting doubt about relativity\'s reality or any suggestion that GPS is currently unreliable (the passage describes correctly-functioning GPS achieving "few-meter accuracy," implying the correction described is already successfully in place). There is no mocking or sarcastic language anywhere in the passage\'s descriptions of the engineering involved.' }
      ]
    }
  ],
  // flattened for the test engine; each carries its passage reference
  questions: [],
  examQuestions: []
};

// Flatten passage questions into flat lists, tagging each with its passage id/title.
// Practice questions come only from `passages` (shown untimed, with explanations);
// timed tests draw only from `examQuestions`, built from the held-out `examPassages`
// — so a timed Reading test never repeats an item the student has already seen.
(function () {
  var r = window.OAT_CONTENT.reading;
  function flatten(passageList, targetArray) {
    passageList.forEach(function (p) {
      p.questions.forEach(function (q) {
        var copy = Object.assign({}, q);
        copy.passageId = p.id;
        copy.passageTitle = p.title;
        targetArray.push(copy);
      });
    });
  }
  flatten(r.passages, r.questions);
  flatten(r.examPassages, r.examQuestions);
  // The test runner looks up passage text by id in `r.passages`, so the
  // held-out exam passages must be discoverable there too. This is safe:
  // practice mode only surfaces a passage if one of its questions appears in
  // `r.questions`, and exam-only passages' questions never do.
  r.passages = r.passages.concat(r.examPassages);
})();
